/// Supplies raw asset bytes. Back it with CASC, loose files, or a cache.
class AssetProvider {
public:
    virtual ~AssetProvider() = default;
    /// Return the bytes of an asset, or empty if it is unavailable.
    virtual std::vector<u8> load(Group group, i32 snoId) = 0;
};

/// An Actor together with the assets it needs to be drawn.
///
/// Only references whose target group is known are followed, and each is
/// optional: a missing dependency leaves its slot empty rather than
/// failing the whole load.
